-- ============================================================================
-- PostgreSQL (plpgsql) translation of oracle/sp_customer_tier.sql and
-- oracle/sp_monthly_report.sql. Apply after schema.sql.
--
-- Run with:   CALL sp_customer_tier();
--             CALL sp_monthly_report('2026-09');
--
-- Transaction handling: the Oracle COMMIT / ROLLBACK statements are not
-- needed here. A CALL runs in its own transaction when issued outside an
-- explicit BEGIN, and a plpgsql block with an EXCEPTION clause is wrapped in
-- a subtransaction that is rolled back automatically when an error is caught.
-- ============================================================================

CREATE OR REPLACE PROCEDURE sp_customer_tier()
LANGUAGE plpgsql
AS $$
DECLARE
    v_tier   varchar(20);
    v_status varchar(20);
    rec      record;
BEGIN
    DELETE FROM customer_tiers;

    FOR rec IN
        SELECT o.customer_id,
               c.customer_name,
               SUM(o.order_total) AS total_spend,
               COUNT(*)           AS order_count
        FROM   orders o
        JOIN   customers c ON c.customer_id = o.customer_id
        WHERE  COALESCE(c.status, 'ACTIVE') = 'ACTIVE'
        GROUP  BY o.customer_id, c.customer_name
        ORDER  BY total_spend, o.customer_id
    LOOP
        IF rec.total_spend >= 1000 THEN
            v_tier := 'GOLD';
        ELSIF rec.total_spend >= 500 THEN
            v_tier := 'SILVER';
        ELSE
            v_tier := 'BRONZE';
        END IF;

        INSERT INTO customer_tiers
            (customer_id, customer_name, total_spend, order_count, tier, computed_at)
        VALUES
            (rec.customer_id, rec.customer_name, rec.total_spend, rec.order_count,
             v_tier, now());
    END LOOP;

    -- Preserves the source's side check: STRICT raises no_data_found when
    -- customers is empty, as the source's one-row lookup did.
    SELECT status INTO STRICT v_status FROM customers LIMIT 1;
END;
$$;


CREATE OR REPLACE PROCEDURE sp_monthly_report(p_month varchar)
LANGUAGE plpgsql
AS $$
DECLARE
    v_row        monthly_report;
    v_has_data   bigint := 0;
    rec          record;
BEGIN
    -- Selecting a constant from a one-row table: always returns 1.
    SELECT COUNT(*) INTO v_has_data FROM (VALUES (1)) AS one_row(x);

    DELETE FROM monthly_report WHERE report_month = p_month;

    FOR rec IN
        SELECT p.category AS category,
               COALESCE(SUM(oi.quantity * oi.unit_price), 0) AS revenue,
               COALESCE(SUM(oi.quantity), 0)                 AS units_sold
        FROM   order_items oi
        JOIN   products p ON p.product_id = oi.product_id
        GROUP  BY p.category
        ORDER  BY revenue DESC, p.category
    LOOP
        v_row.report_month := p_month;
        v_row.category     := rec.category;
        v_row.revenue      := rec.revenue;
        v_row.units_sold   := rec.units_sold;

        INSERT INTO monthly_report
            (report_month, category, revenue, units_sold)
        VALUES
            (v_row.report_month, v_row.category, v_row.revenue, v_row.units_sold);
    END LOOP;

    IF v_has_data = 0 THEN
        RAISE EXCEPTION 'no data for report month %', p_month
            USING ERRCODE = 'MR001';
    END IF;
EXCEPTION
    -- Equivalent of the source's "WHEN e_no_data THEN ROLLBACK": the block's
    -- DELETE and INSERTs are undone automatically, and the call returns normally.
    WHEN SQLSTATE 'MR001' THEN
        NULL;
    WHEN OTHERS THEN
        RAISE;
END;
$$;
